const rotationRtPublishedEntries = `-- name: RotationRtPublishedEntries :many
SELECT DISTINCT se.value_entry_id FROM rotation_runs ru JOIN rotations ro ON ro.org_id=ru.org_id AND ro.project_id=ru.project_id AND ro.environment_id=ru.environment_id AND ro.id=ru.rotation_id JOIN snapshots sn ON sn.org_id=ru.org_id AND sn.project_id=ru.project_id AND sn.environment_id=ru.environment_id AND sn.revision=ru.published_revision JOIN snapshot_entries se ON se.snapshot_id=sn.id AND se.org_id=sn.org_id AND se.project_id=sn.project_id AND se.environment_id=sn.environment_id WHERE ru.org_id=?1 AND ru.project_id=?2 AND ru.environment_id=?3 AND se.key_id=?4 AND (ro.key_id=?4 OR ro.username_key_id=?4) AND ru.published_revision>=?5
`

type RotationRtPublishedEntriesParams struct {
	ChainOrg     string
	ChainProject string
	ChainEnv     string
	KeyID        string
	FromRevision sql.NullInt64
}

// The value versions a key legitimately serves after a run: the entries pinned by
// the snapshot of every published revision of any run (this one or a later one)
// that drove the key. Ids only; no secret is read.
func (q *Queries) RotationRtPublishedEntries(ctx context.Context, arg RotationRtPublishedEntriesParams) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, rotationRtPublishedEntries,
		arg.ChainOrg,
		arg.ChainProject,
		arg.ChainEnv,
		arg.KeyID,
		arg.FromRevision,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var value_entry_id string
		if err := rows.Scan(&value_entry_id); err != nil {
			return nil, err
		}
		items = append(items, value_entry_id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const rotationRtSetNextRun = `-- name: RotationRtSetNextRun :execrows
UPDATE rotations SET next_run_at=?1,updated_at=?2 WHERE id=?3 AND org_id=?4 AND project_id=?5 AND environment_id=?6 AND state='active'
`

type RotationRtSetNextRunParams struct {
	NextRunAt    sql.NullString
	Now          string
	RotationID   string
	ChainOrg     string
	ChainProject string
	ChainEnv     string
}

// The schedule moves, never the generation: the run that is in flight asserts the
// generation it started under, so a schedule write must not invalidate it.
func (q *Queries) RotationRtSetNextRun(ctx context.Context, arg RotationRtSetNextRunParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, rotationRtSetNextRun,
		arg.NextRunAt,
		arg.Now,
		arg.RotationID,
		arg.ChainOrg,
		arg.ChainProject,
		arg.ChainEnv,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const rotationRtSettleRun = `-- name: RotationRtSettleRun :execrows
UPDATE rotation_runs SET phase=?1,phase_at=?2,last_error=?3,next_attempt_at=?4,candidate_valid_until=COALESCE(?5,candidate_valid_until),published_revision=COALESCE(?6,published_revision),lease_owner=CASE WHEN CAST(?7 AS INTEGER)=1 THEN lease_owner ELSE NULL END,lease_expires_at=CASE WHEN CAST(?7 AS INTEGER)=1 THEN lease_expires_at ELSE NULL END WHERE id=?8 AND org_id=?9 AND project_id=?10 AND environment_id=?11 AND lease_owner=?12 AND lease_expires_at>?2 AND lease_claim_token=?13 AND phase IN (/*SLICE:from_phases*/?)
`

type RotationRtSettleRunParams struct {
	Phase             string
	Now               string
	LastError         sql.NullString
	NextAttemptAt     string
	ValidUntilAt      sql.NullString
	PublishedRevision sql.NullInt64
	KeepLease         int64
	ID                string
	ChainOrg          string
	ChainProject      string
	ChainEnv          string
	Worker            sql.NullString
	ClaimToken        int64
	FromPhases        []string
}

// The one settling write. It names the phases it may leave, so it is both the
// exact-row fence and the "fenced claim write" of crash-safety rule 8: it waits on
// a row lock a publish transaction holds, and matches zero rows once the run has
// left those phases. A settle that keeps the lease passes keep_lease.
func (q *Queries) RotationRtSettleRun(ctx context.Context, arg RotationRtSettleRunParams) (int64, error) {
	query := rotationRtSettleRun
	var queryParams []interface{}
	queryParams = append(queryParams, arg.Phase)
	queryParams = append(queryParams, arg.Now)
	queryParams = append(queryParams, arg.LastError)
	queryParams = append(queryParams, arg.NextAttemptAt)
	queryParams = append(queryParams, arg.ValidUntilAt)
	queryParams = append(queryParams, arg.PublishedRevision)
	queryParams = append(queryParams, arg.KeepLease)
	queryParams = append(queryParams, arg.ID)
	queryParams = append(queryParams, arg.ChainOrg)
	queryParams = append(queryParams, arg.ChainProject)
	queryParams = append(queryParams, arg.ChainEnv)
	queryParams = append(queryParams, arg.Worker)
	queryParams = append(queryParams, arg.ClaimToken)
	if len(arg.FromPhases) > 0 {
		for _, v := range arg.FromPhases {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:from_phases*/?", strings.Repeat(",?", len(arg.FromPhases))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:from_phases*/?", "NULL", 1)
	}
	result, err := q.db.ExecContext(ctx, query, queryParams...)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const rotationRtSnapshotPublishedAt = `-- name: RotationRtSnapshotPublishedAt :one
SELECT published_at FROM snapshots WHERE org_id=?1 AND project_id=?2 AND environment_id=?3 AND revision=?4
`

type RotationRtSnapshotPublishedAtParams struct {
	ChainOrg     string
	ChainProject string
	ChainEnv     string
	Revision     int64
}

// The commit time of the snapshot a run published: the single anchor P of the
// failure schedule. It is the publish transaction's own timestamp.
func (q *Queries) RotationRtSnapshotPublishedAt(ctx context.Context, arg RotationRtSnapshotPublishedAtParams) (string, error) {
	row := q.db.QueryRowContext(ctx, rotationRtSnapshotPublishedAt,
		arg.ChainOrg,
		arg.ChainProject,
		arg.ChainEnv,
		arg.Revision,
	)
	var published_at string
	err := row.Scan(&published_at)
	return published_at, err
}
